<?php
require_once __DIR__.'/includes/letters.php';LetterModule::requireCapability('settings');$pageTitle='امضاکنندگان نامه';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/letter-signatures.php');}try{$id=(int)($_POST['id']??0);$name=trim((string)($_POST['signer_name']??''));if($name==='')throw new InvalidArgumentException('نام امضاکننده الزامی است.');$current=$id?Database::fetch('SELECT * FROM letter_signatures WHERE id=?',[$id]):[];$signature=$current['signature_path']??null;$stamp=$current['stamp_path']??null;foreach(['signature'=>'signature','stamp'=>'stamp'] as $input=>$category){if(($_FILES[$input]['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$up=letter_private_upload($_FILES[$input],$category,Upload::IMAGE_EXTENSIONS,2*1024*1024);if(!$up['ok'])throw new InvalidArgumentException($up['error']);if($input==='signature')$signature=$up['file_path'];else $stamp=$up['file_path'];}}$data=[$name,trim((string)($_POST['signer_title']??'')),$signature,$stamp,(int)($_POST['user_id']??0)?:null,isset($_POST['is_active'])?1:0];if($id)Database::execute('UPDATE letter_signatures SET signer_name=?,signer_title=?,signature_path=?,stamp_path=?,user_id=?,is_active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO letter_signatures(signer_name,signer_title,signature_path,stamp_path,user_id,is_active,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,NOW(),NOW())',[...$data,(int)Auth::user()['id']]);Auth::log((int)Auth::user()['id'],$id?'signature_updated':'signature_created','letter_signatures',$id?:((int)Database::lastInsertId()));flash('اطلاعات امضاکننده ذخیره شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Letter signature: '.$e->getMessage());flash('ذخیره امضا انجام نشد.','danger');}redirect('/admin/letter-signatures.php');}
$edit=isset($_GET['edit'])?Database::fetch('SELECT * FROM letter_signatures WHERE id=?',[(int)$_GET['edit']]):null;$items=Database::fetchAll('SELECT s.*,u.name user_name FROM letter_signatures s LEFT JOIN users u ON u.id=s.user_id ORDER BY s.is_active DESC,s.signer_name');$users=Database::fetchAll('SELECT id,name,department FROM users WHERE status="active" ORDER BY name');require __DIR__.'/../views/partials/admin-header.php';?>
